134	/// Transforms a [`Paint`] into a [`sk::Paint`].
135	/// Applying the necessary transform, if the paint is a gradient.
136	///
137	/// `gradient_map` is used to scale and move the gradient being sampled,
138	/// this is used to line up the stroke and the fill of a shape.
139	pub fn to_sk_paint<'a>(
140	    paint: &Paint,
141	    state: State,
142	    on_text: bool,
143	    pixmap: &'a mut Option<Arc<sk::Pixmap>>,
144	    shape: Option<&Shape>,
145	    include_stroke_in_bbox: bool,
146	) -> sk::Paint<'a> {
147	    /// Actual sampling of the gradient, cached for performance.
148	    #[comemo::memoize]
149	    fn cached(
150	        gradient: &Gradient,
151	        width: u32,
152	        height: u32,
153	        gradient_map: Option<(Point, Axes<Ratio>)>,
154	    ) -> Arc<sk::Pixmap> {
155	        let (offset, scale) =
156	            gradient_map.unwrap_or_else(|| (Point::zero(), Axes::splat(Ratio::one())));
157	        let mut pixmap = sk::Pixmap::new(width.max(1), height.max(1)).unwrap();
158	        for x in 0..width {
159	            for y in 0..height {
160	                let color = gradient.sample_at(
161	                    (
162	                        (x as f32 + offset.x.to_f32()) * scale.x.get() as f32,
163	                        (y as f32 + offset.y.to_f32()) * scale.y.get() as f32,
164	                    ),
165	                    (width as f32, height as f32),
166	                );
167	
168	                pixmap.pixels_mut()[(y * width + x) as usize] =
169	                    to_sk_color(color.to_process()).premultiply().to_color_u8();
170	            }
171	        }
172	
173	        Arc::new(pixmap)
174	    }
175	
176	    let (item_size, fill_transform, gradient_map) = if let Some(shape) = shape {
177	        let bbox = shape.bbox(include_stroke_in_bbox);
178	        let fill_transform =
179	            sk::Transform::from_translate(bbox.min.x.to_f32(), bbox.min.y.to_f32());
180	        let gradient_map = match shape.geometry {
181	            // Special handling for rectangles (mirrors gradients for negative sizes)
182	            Geometry::Rect(rect) => Some((
183	                Point::new(
184	                    if rect.x.signum() < 0.0 { -bbox.size().x } else { Abs::zero() },
185	                    if rect.y.signum() < 0.0 { -bbox.size().y } else { Abs::zero() },
186	                ) * state.pixel_per_pt as f64,
187	                Axes::new(Ratio::new(rect.x.signum()), Ratio::new(rect.y.signum())),
188	            )),
189	            _ => None,
190	        };
191	        (bbox.size(), Some(fill_transform), gradient_map)
192	    } else {
193	        (Size::zero(), None, None)
194	    };
195	
196	    let mut sk_paint: sk::Paint<'_> = sk::Paint::default();
197	    match paint {
198	        Paint::Solid(color) => {
199	            sk_paint.set_color(to_sk_color(color.to_process()));
200	            sk_paint.anti_alias = true;
201	        }
202	        Paint::Gradient(gradient) => {
203	            let relative = gradient.unwrap_relative(on_text);
204	            let container_size = match relative {
205	                RelativeTo::Self_ => item_size,
206	                RelativeTo::Parent => state.size,
207	            };
208	
209	            let fill_transform = match relative {
210	                RelativeTo::Self_ => fill_transform.unwrap_or_default(),
211	                RelativeTo::Parent => state
212	                    .container_transform
213	                    .post_concat(state.transform.invert().unwrap()),
214	            };
215	
216	            let gradient_map = match relative {
217	                RelativeTo::Self_ => gradient_map,
218	                RelativeTo::Parent => None,
219	            };
220	
221	            let width =
222	                (container_size.x.to_f32().abs() * state.pixel_per_pt).ceil() as u32;
223	            let height =
224	                (container_size.y.to_f32().abs() * state.pixel_per_pt).ceil() as u32;
225	
226	            *pixmap = Some(cached(
227	                gradient,
228	                width.max(state.pixel_per_pt.ceil() as u32),
229	                height.max(state.pixel_per_pt.ceil() as u32),
230	                gradient_map,
231	            ));
232	
233	            // We can use FilterQuality::Nearest here because we're
234	            // rendering to a pixmap that is already at native resolution.
235	            sk_paint.shader = sk::Pattern::new(
236	                pixmap.as_ref().unwrap().as_ref().as_ref(),
237	                sk::SpreadMode::Pad,
238	                sk::FilterQuality::Nearest,
239	                1.0,
240	                fill_transform.pre_scale(
241	                    container_size.x.signum() as f32 / state.pixel_per_pt,
242	                    container_size.y.signum() as f32 / state.pixel_per_pt,
243	                ),
244	            );
245	
246	            sk_paint.anti_alias = gradient.anti_alias();
247	        }
248	        Paint::Tiling(tilings) => {
249	            let relative = tilings.unwrap_relative(on_text);
250	
251	            let fill_transform = match relative {
252	                RelativeTo::Self_ => fill_transform.unwrap_or_default(),
253	                RelativeTo::Parent => state
254	                    .container_transform
255	                    .post_concat(state.transform.invert().unwrap()),
256	            };
257	
258	            let canvas = render_tiling_frame(&state, tilings);
259	            *pixmap = Some(Arc::new(canvas));
260	
261	            let base_offset = match relative {
262	                RelativeTo::Self_ => {
263	                    gradient_map.map(|(offset, _)| -offset).unwrap_or_default()
264	                }
265	                RelativeTo::Parent => Point::zero(),
266	            };
267	
268	            // Create the shader
269	            sk_paint.shader = sk::Pattern::new(
270	                pixmap.as_ref().unwrap().as_ref().as_ref(),
271	                sk::SpreadMode::Repeat,
272	                sk::FilterQuality::Nearest,
273	                1.0,
274	                fill_transform
275	                    .pre_concat(to_sk_transform(&tilings.transform()))
276	                    .pre_scale(1.0 / state.pixel_per_pt, 1.0 / state.pixel_per_pt)
277	                    .pre_translate(base_offset.x.to_f32(), base_offset.y.to_f32()),
278	            );
279	        }
280	    }
281	
282	    sk_paint
283	}
