86	/// Convert a Typst curve into a tiny-skia path.
87	pub fn convert_curve(curve: &Curve) -> Option<sk::Path> {
88	    let mut builder = sk::PathBuilder::new();
89	    for elem in &curve.0 {
90	        match elem {
91	            CurveItem::Move(p) => {
92	                builder.move_to(p.x.to_f32(), p.y.to_f32());
93	            }
94	            CurveItem::Line(p) => {
95	                builder.line_to(p.x.to_f32(), p.y.to_f32());
96	            }
97	            CurveItem::Cubic(p1, p2, p3) => {
98	                builder.cubic_to(
99	                    p1.x.to_f32(),
100	                    p1.y.to_f32(),
101	                    p2.x.to_f32(),
102	                    p2.y.to_f32(),
103	                    p3.x.to_f32(),
104	                    p3.y.to_f32(),
105	                );
106	            }
107	            CurveItem::Close => {
108	                builder.close();
109	            }
110	        }
111	    }
112	    builder.finish()
113	}
114	
115	pub fn to_sk_line_cap(cap: LineCap) -> sk::LineCap {
116	    match cap {
117	        LineCap::Butt => sk::LineCap::Butt,
118	        LineCap::Round => sk::LineCap::Round,
119	        LineCap::Square => sk::LineCap::Square,
120	    }
121	}
122	
123	pub fn to_sk_line_join(join: LineJoin) -> sk::LineJoin {
124	    match join {
125	        LineJoin::Miter => sk::LineJoin::Miter,
126	        LineJoin::Round => sk::LineJoin::Round,
127	        LineJoin::Bevel => sk::LineJoin::Bevel,
128	    }
129	}
130	
131	pub fn to_sk_dash_pattern(dash: &DashPattern<Abs, Abs>) -> Option<sk::StrokeDash> {
132	    // tiny-skia only allows dash patterns with an even number of elements,
133	    // while pdf allows any number.
